#pragma once

// PLEASE DO NOT EDIT THIS FILE, IT IS GENERATED AND WILL BE OVERWRITTEN:
// https://github.com/ccxt/ccxt/blob/master/CONTRIBUTING.md#how-to-contribute-code

#include "../../BaseTest.Bridge.h"

// forward declarations - TS hoists function declarations, C++ does not
void testClone();

void testClone()
{
    ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("sampleexchange") },
    });
    std::any obj1 = ccxt::dict {
        { std::string("a"), 1 },
        { std::string("b"), ccxt::list{1, 2, 3} },
        { std::string("c"), ccxt::list{ccxt::dict {
    { std::string("test1"), 1 },
    { std::string("test2"), 1 },
}} },
        { std::string("d"), std::any{} },
        { std::string("e"), std::string("not_undefined") },
        { std::string("sub"), ccxt::dict {
            { std::string("a"), 1 },
            { std::string("b"), ccxt::list{1, 2} },
            { std::string("c"), ccxt::list{ccxt::dict {
    { std::string("test1"), 1 },
    { std::string("test2"), 2 },
}} },
            { std::string("d"), std::any{} },
            { std::string("e"), std::string("not_undefined") },
            { std::string("other1"), std::string("x") },
        } },
        { std::string("other1"), std::string("x") },
    };
    std::any obj2 = ccxt::dict {
        { std::string("a"), 2 },
        { std::string("b"), ccxt::list{3, 4} },
        { std::string("c"), ccxt::list{ccxt::dict {
    { std::string("test1"), 2 },
    { std::string("test3"), 3 },
}} },
        { std::string("d"), std::string("not_undefined") },
        { std::string("e"), std::any{} },
        { std::string("sub"), ccxt::dict {
            { std::string("a"), 2 },
            { std::string("b"), ccxt::list{3, 4} },
            { std::string("c"), ccxt::list{ccxt::dict {
    { std::string("test1"), 2 },
    { std::string("test3"), 3 },
}} },
            { std::string("d"), std::string("not_undefined") },
            { std::string("e"), std::any{} },
            { std::string("other2"), std::string("y") },
        } },
        { std::string("other2"), std::string("y") },
    };
    // deepExtend
    std::any deepExtended = exchange.deepExtend(obj1, obj2);
    std::any compareTo = ccxt::dict {
        { std::string("a"), 2 },
        { std::string("b"), ccxt::list{3, 4} },
        { std::string("c"), ccxt::list{ccxt::dict {
    { std::string("test1"), 2 },
    { std::string("test3"), 3 },
}} },
        { std::string("d"), std::string("not_undefined") },
        { std::string("e"), std::any{} },
        { std::string("sub"), ccxt::dict {
            { std::string("a"), 2 },
            { std::string("b"), ccxt::list{3, 4} },
            { std::string("c"), ccxt::list{ccxt::dict {
    { std::string("test1"), 2 },
    { std::string("test3"), 3 },
}} },
            { std::string("d"), std::string("not_undefined") },
            { std::string("e"), std::any{} },
            { std::string("other1"), std::string("x") },
            { std::string("other2"), std::string("y") },
        } },
        { std::string("other1"), std::string("x") },
        { std::string("other2"), std::string("y") },
    };
    // todo: results are different across langs.
    // to avoid delay to this PR, I comment out this now, but will return to this after this PR merged
    assertDeepEqual(exchange, std::any{}, std::string("testDeepExtend"), deepExtended, compareTo);
    // -------------------------------------------------------------------------
    // test immutability / no cross-mutation between clone and original
    // -------------------------------------------------------------------------
    // --- test A: shallow-object clone – mutating the clone must not affect original ---
    std::any simpleOrig = ccxt::dict {
        { std::string("x"), 1 },
        { std::string("y"), std::string("hello") },
        { std::string("z"), std::any{} },
    };
    std::any simpleClone = exchange.clone(simpleOrig);
    assertTrue(isEqual(::getValue(simpleClone, std::string("x")), 1), std::string("clone A: x"));
    assertTrue(isEqual(::getValue(simpleClone, std::string("y")), std::string("hello")), std::string("clone A: y"));
    assertTrue(isEqual(::getValue(simpleClone, std::string("z")), std::any{}), std::string("clone A: z"));
    ::setValue(simpleClone, std::string("x"), 999);
    ::setValue(simpleClone, std::string("y"), std::string("mutated"));
    assertTrue(isEqual(::getValue(simpleOrig, std::string("x")), 1), std::string("clone A: mutating clone must not change original x"));
    assertTrue(isEqual(::getValue(simpleOrig, std::string("y")), std::string("hello")), std::string("clone A: mutating clone must not change original y"));
    // mutating the original must not affect an already-taken clone
    ::setValue(simpleOrig, std::string("x"), 42);
    assertTrue(isEqual(::getValue(simpleClone, std::string("x")), 999), std::string("clone A: mutating original must not change clone x"));
    // -------------------------------------------------------------------------
    // --- test B: nested object – verify clone is a shallow copy (top-level keys independent) ---
    std::any nestedOrig = ccxt::dict {
        { std::string("top"), std::string("original") },
        { std::string("arr"), ccxt::list{10, 20, 30} },
        { std::string("sub"), ccxt::dict {
            { std::string("inner"), std::string("original") },
        } },
    };
    std::any nestedClone = exchange.clone(nestedOrig);
    // top-level scalar: independent
    ::setValue(nestedClone, std::string("top"), std::string("cloned"));
    assertTrue(isEqual(::getValue(nestedOrig, std::string("top")), std::string("original")), std::string("clone B: top-level scalar independence – original unchanged"));
    assertTrue(isEqual(::getValue(nestedClone, std::string("top")), std::string("cloned")), std::string("clone B: top-level scalar independence – clone updated"));
    ::setValue(nestedOrig, std::string("top"), std::string("changed_orig"));
    assertTrue(isEqual(::getValue(nestedClone, std::string("top")), std::string("cloned")), std::string("clone B: changing original top must not affect clone"));
    // -------------------------------------------------------------------------
    // --- test C: cloning an empty object ---
    std::any emptyClone = exchange.clone(ccxt::dict {});
    assertTrue(isEqual(getArrayLength(getObjectKeys(emptyClone)), 0), std::string("clone C: cloning empty object gives empty object"));
    ::setValue(emptyClone, std::string("newKey"), std::string("injected"));
    // confirm the operation didn't throw and the value was set
    assertTrue(isEqual(::getValue(emptyClone, std::string("newKey")), std::string("injected")), std::string("clone C: can add key to clone of empty object"));
    // -------------------------------------------------------------------------
    // --- test D: cloning an object with undefined values preserves those keys ---
    std::any withUndef = ccxt::dict {
        { std::string("present"), std::string("yes") },
        { std::string("absent"), std::any{} },
    };
    std::any undefClone = exchange.clone(withUndef);
    assertTrue(inOp(undefClone, std::string("present")), std::string("clone D: present key must exist in clone"));
    assertTrue(isEqual(::getValue(undefClone, std::string("present")), std::string("yes")), std::string("clone D: present value preserved"));
    assertTrue(inOp(undefClone, std::string("absent")), std::string("clone D: undefined key must still exist in clone"));
    assertTrue(isEqual(::getValue(undefClone, std::string("absent")), std::any{}), std::string("clone D: undefined value preserved"));
    // mutate clone – original untouched
    ::setValue(undefClone, std::string("present"), std::string("no"));
    assertTrue(isEqual(::getValue(withUndef, std::string("present")), std::string("yes")), std::string("clone D: mutating clone must not change original"));
    // -------------------------------------------------------------------------
    // --- test E: multi-step: clone → mutate clone → re-clone original → compare ---
    std::any masterOrig = ccxt::dict {
        { std::string("a"), 1 },
        { std::string("b"), 2 },
        { std::string("c"), 3 },
    };
    std::any clone1 = exchange.clone(masterOrig);
    ::setValue(clone1, std::string("a"), 100);
    ::setValue(clone1, std::string("d"), 999); // add extra key
    // original still pristine
    assertTrue(isEqual(::getValue(masterOrig, std::string("a")), 1), std::string("clone E: original a untouched after clone1 mutation"));
    assertTrue(!isTrue((inOp(masterOrig, std::string("d")))), std::string("clone E: extra key must not appear in original"));
    // second independent clone from the still-pristine original
    std::any clone2 = exchange.clone(masterOrig);
    assertTrue(isEqual(::getValue(clone2, std::string("a")), 1), std::string("clone E: clone2 starts from pristine original"));
    assertTrue(!isTrue((inOp(clone2, std::string("d")))), std::string("clone E: clone2 must not inherit clone1 extra key"));
    // mutate clone2 differently
    ::setValue(clone2, std::string("b"), 200);
    assertTrue(isEqual(::getValue(clone1, std::string("b")), 2), std::string("clone E: clone1.b unaffected by clone2 mutation"));
    assertTrue(isEqual(::getValue(masterOrig, std::string("b")), 2), std::string("clone E: original.b unaffected by clone2 mutation"));
}

